  "Input":{"oneOf":[{"$ref":"#/$defs/Text"},{"type":"object","additionalProperties":false,"required":["schema","value"],"properties":{"schema":{"$ref":"#/$defs/Ref"},"value":{"$ref":"#/$defs/JSON"}}}]},
  "Profile":{"type":"object","additionalProperties":false,"required":["id","revision"],"properties":{"id":{"$ref":"#/$defs/Ref"},"revision":{"$ref":"#/$defs/Pos"}}},
  "Limits":{"type":"object","additionalProperties":false,"properties":{"turn":{"$ref":"#/$defs/Budget"},"session":{"$ref":"#/$defs/Budget"}}},
  "Workdir":{"type":"object","additionalProperties":false,"description":"The working folder: a folder under an admitted node root. The stock root bee.node:machine is the machine root /, so path is the folder's absolute path without its leading slash.","properties":{"root_ref":{"$ref":"#/$defs/Ref"},"path":{"type":"string","maxLength":4096}},"required":["root_ref","path"]},
  "ManagedSpec":{"type":"object","additionalProperties":false,"required":["definition"],"properties":{"definition":{"$ref":"#/$defs/Ref"},"profile":{"$ref":"#/$defs/Profile"},"workdir":{"$ref":"#/$defs/Workdir"},"workspace":{"type":"string","pattern":"^[0-9a-f]{32}$"}}},
