  "Evidence":{"type":"object","additionalProperties":false,"required":["summary","artifacts"],"properties":{"summary":{"$ref":"#/$defs/Text"},"artifacts":{"$ref":"#/$defs/Refs"}}},
  "ActivityEvidence":{"type":"object","additionalProperties":false,"required":["kind","turn","last_progress_at_ms","quiet_period_ms","quiet_for_ms"],"properties":{"kind":{"const":"quiet"},"turn":{"$ref":"#/$defs/Ref"},"last_progress_at_ms":{"$ref":"#/$defs/Nat"},"quiet_period_ms":{"$ref":"#/$defs/Pos"},"quiet_for_ms":{"$ref":"#/$defs/Nat"}}},
  "Fault":{"type":"object","additionalProperties":false,"required":["code","message","retry"],"properties":{"code":{"type":"string","minLength":1,"maxLength":128},"message":{"$ref":"#/$defs/Text"},"retry":{"enum":["never","same_key","refresh","reconcile"]},"operation_key":{"$ref":"#/$defs/Key"},"operation":{"$ref":"#/$defs/OpRef"},"current_revision":{"$ref":"#/$defs/Pos"},"evidence":{"$ref":"#/$defs/Evidence"},"retry_after_ms":{"$ref":"#/$defs/Nat"}}},
  "Reply":{"oneOf":[{"type":"object","additionalProperties":false,"required":["ok","value"],"properties":{"ok":{"const":true},"value":{}}},{"type":"object","additionalProperties":false,"required":["ok","error"],"properties":{"ok":{"const":false},"error":{"$ref":"#/$defs/Fault"}}}]},
  "MutationReply":{"allOf":[{"$ref":"#/$defs/Reply"},{"properties":{"error":{"required":["operation_key"]}}}]},
  "Usage":{"type":"object","additionalProperties":false,"properties":{"input_tokens":{"$ref":"#/$defs/Nat"},"output_tokens":{"$ref":"#/$defs/Nat"},"cached_tokens":{"$ref":"#/$defs/Nat"},"cost_decimal":{"type":"string","maxLength":40,"pattern":"^[0-9]+[.]?[0-9]*$"},"currency":{"type":"string","pattern":"^[A-Z]{3}$"}},"dependentRequired":{"cost_decimal":["currency"],"currency":["cost_decimal"]}},
  "Result":{"oneOf":[{"type":"object","additionalProperties":false,"required":["outcome","schema","value","artifacts","usage"],"properties":{"outcome":{"const":"succeeded"},"schema":{"$ref":"#/$defs/Ref"},"value":{"$ref":"#/$defs/JSON"},"artifacts":{"$ref":"#/$defs/Refs"},"usage":{"$ref":"#/$defs/Usage"}}},{"type":"object","additionalProperties":false,"required":["outcome","error","artifacts"],"properties":{"outcome":{"enum":["failed","cancelled","rejected"]},"error":{"$ref":"#/$defs/Fault"},"artifacts":{"$ref":"#/$defs/Refs"}}},{"type":"object","additionalProperties":false,"required":["outcome","error","artifacts","evidence"],"properties":{"outcome":{"const":"budget_exceeded"},"error":{"$ref":"#/$defs/Fault"},"artifacts":{"$ref":"#/$defs/Refs"},"evidence":{"$ref":"#/$defs/Evidence"}}}]},
  "Action":{"type":"object","additionalProperties":false,"required":["operation","label"],"properties":{"operation":{"$ref":"#/$defs/Ref"},"label":{"$ref":"#/$defs/Text"}}},
