  "Blocker":{"type":"object","additionalProperties":false,"required":["kind","message","subject","actions"],"properties":{"kind":{"enum":["budget","authority","capacity","recovery","stalled"]},"message":{"$ref":"#/$defs/Text"},"subject":{"$ref":"#/$defs/Ref"},"actions":{"$ref":"#/$defs/Actions"}}},
  "WorkReceipt":{"type":"object","additionalProperties":false,"required":["work","session","operation","committed_at","sequence","kind","state","output_schema","sender"],"properties":{"work":{"$ref":"#/$defs/WorkRef"},"session":{"$ref":"#/$defs/SessionRef"},"operation":{"$ref":"#/$defs/OpRef"},"committed_at":{"$ref":"#/$defs/Time"},"sequence":{"$ref":"#/$defs/Pos"},"kind":{"const":"request"},"state":{"const":"queued"},"output_schema":{"$ref":"#/$defs/Ref"},"sender":{"$ref":"#/$defs/Sender"}}},
  "WorkState":{"type":"object","additionalProperties":false,"required":["work","session","sender","revision","phase","cancelling"],"properties":{"work":{"$ref":"#/$defs/WorkRef"},"session":{"$ref":"#/$defs/SessionRef"},"sender":{"$ref":"#/$defs/Sender"},"revision":{"$ref":"#/$defs/Pos"},"phase":{"enum":["queued","reserved","accepted","settled"]},"cancelling":{"type":"boolean"},"blocker":{"$ref":"#/$defs/Blocker"},"uncertainty":{"$ref":"#/$defs/Evidence"},"result":{"$ref":"#/$defs/Result"}},"oneOf":[{"properties":{"phase":{"const":"settled"},"cancelling":{"const":false}},"required":["result"],"not":{"anyOf":[{"required":["blocker"]},{"required":["uncertainty"]}]}},{"properties":{"phase":{"enum":["queued","reserved","accepted"]}},"not":{"required":["result"]}}]},
  "ControlReceipt":{"type":"object","additionalProperties":false,"required":["operation","subject","state","effect"],"properties":{"operation":{"$ref":"#/$defs/OpRef"},"subject":{"oneOf":[{"$ref":"#/$defs/WorkRef"},{"$ref":"#/$defs/SessionRef"}]},"state":{"const":"requested"},"effect":{"enum":["cancel","close"]}}},
  "ControlResult":{"oneOf":[{"type":"object","additionalProperties":false,"required":["effect","state","work","evidence"],"properties":{"effect":{"const":"cancel"},"state":{"enum":["stopped","already_terminal"]},"work":{"$ref":"#/$defs/WorkRef"},"evidence":{"$ref":"#/$defs/Evidence"}}},{"type":"object","additionalProperties":false,"required":["effect","state","session","cleanup"],"properties":{"effect":{"const":"close"},"state":{"const":"closed"},"session":{"$ref":"#/$defs/SessionRef"},"cleanup":{"enum":["complete","pending","uncertain"]}}}]},
  "OperationReceipt":{"oneOf":[{"$ref":"#/$defs/OpenReceipt"},{"$ref":"#/$defs/WorkReceipt"},{"$ref":"#/$defs/ControlReceipt"}]},
  "OperationResult":{"oneOf":[{"type":"object","additionalProperties":false,"required":["kind","value"],"properties":{"kind":{"const":"receipt"},"value":{"$ref":"#/$defs/OperationReceipt"}}},{"type":"object","additionalProperties":false,"required":["kind","value"],"properties":{"kind":{"const":"control"},"value":{"$ref":"#/$defs/ControlResult"}}},{"type":"object","additionalProperties":false,"required":["kind","result"],"properties":{"kind":{"const":"result"},"result":{"$ref":"#/$defs/Result"}}}]},
  "Await":{"type":"object","additionalProperties":false,"required":["subject_kind","subject","cursor","tag"],"properties":{"subject_kind":{"enum":["work","operation"]},"subject":{"$ref":"#/$defs/Subject"},"cursor":{"$ref":"#/$defs/Cursor"},"tag":{"enum":["ready","pending","blocked","uncertain"]},"result":{},"reason":{"const":"timeout"},"blocker":{"$ref":"#/$defs/Blocker"},"evidence":{"$ref":"#/$defs/Evidence"}},"allOf":[{"oneOf":[{"properties":{"subject_kind":{"const":"work"},"subject":{"$ref":"#/$defs/WorkRef"},"result":{"$ref":"#/$defs/Result"}}},{"properties":{"subject_kind":{"const":"operation"},"subject":{"$ref":"#/$defs/OpRef"},"result":{"$ref":"#/$defs/OperationResult"}}}]},{"$ref":"#/$defs/AwaitBranches"}]},
  "AwaitBranches":{"oneOf":[{"properties":{"tag":{"const":"ready"}},"required":["result"],"not":{"anyOf":[{"required":["reason"]},{"required":["blocker"]},{"required":["evidence"]}]}},{"properties":{"tag":{"const":"pending"}},"required":["reason"],"not":{"anyOf":[{"required":["result"]},{"required":["blocker"]},{"required":["evidence"]}]}},{"properties":{"tag":{"const":"blocked"}},"required":["blocker"],"not":{"anyOf":[{"required":["result"]},{"required":["reason"]},{"required":["evidence"]}]}},{"properties":{"tag":{"const":"uncertain"}},"required":["evidence"],"not":{"anyOf":[{"required":["result"]},{"required":["reason"]},{"required":["blocker"]}]}}]},
  "JoinResult":{"type":"object","additionalProperties":false,"required":["succeeded","winners"],"properties":{"succeeded":{"type":"boolean"},"winners":{"type":"array","maxItems":64,"uniqueItems":true,"items":{"$ref":"#/$defs/WorkRef"}},"values":{"type":"array","maxItems":64,"items":{"$ref":"#/$defs/JSON"}}},"if":{"properties":{"succeeded":{"const":true}}},"then":{"required":["values"],"properties":{"winners":{"minItems":1}}},"else":{"not":{"required":["values"]}}},
  "JoinAwait":{"type":"object","additionalProperties":false,"required":["subject_kind","subject","cursor","tag","children"],"properties":{"subject_kind":{"const":"join"},"subject":{"$ref":"#/$defs/JoinRef"},"cursor":{"$ref":"#/$defs/Cursor"},"tag":{"enum":["ready","pending","blocked","uncertain"]},"children":{"type":"array","minItems":1,"maxItems":64,"items":{"allOf":[{"$ref":"#/$defs/Await"},{"properties":{"subject_kind":{"const":"work"}}}]}},"result":{"$ref":"#/$defs/JoinResult"},"reason":{"const":"timeout"},"blocker":{"$ref":"#/$defs/Blocker"},"evidence":{"$ref":"#/$defs/Evidence"}},"allOf":[{"$ref":"#/$defs/AwaitBranches"}]},
  "Continuity":{"type":"object","additionalProperties":false,"required":["mode"],"properties":{"mode":{"enum":["exact","provider_resume","reconstructed","fresh"]},"evidence":{"$ref":"#/$defs/Evidence"}}},
  "LastResult":{"type":"object","additionalProperties":false,"required":["work","outcome","summary","at"],"properties":{"work":{"$ref":"#/$defs/WorkRef"},"outcome":{"enum":["succeeded","failed","cancelled","rejected","budget_exceeded"]},"summary":{"type":"string","maxLength":4096},"at":{"$ref":"#/$defs/Time"}}},
  "SessionSnapshot":{"type":"object","additionalProperties":false,"required":["session","revision","incarnation","title","lifecycle","activity","execution","queue_count","effective_limits","continuity","actions"],"properties":{"terminal":{"type":"boolean"},"thread_ref":{"type":"string","minLength":1,"maxLength":160},"workspace":{"type":"string","minLength":1,"maxLength":32},"driver":{"type":"string","minLength":1,"maxLength":256},"provider":{"type":"string","minLength":1,"maxLength":128},"definition":{"type":"string","minLength":1,"maxLength":256},"last_result":{"$ref":"#/$defs/LastResult"},"session":{"$ref":"#/$defs/SessionRef"},"revision":{"$ref":"#/$defs/Pos"},"incarnation":{"$ref":"#/$defs/Pos"},"title":{"type":"string","maxLength":512},"lifecycle":{"enum":["opening","active","suspended","closing","closed"]},"activity":{"enum":["idle","working","blocked","stalled"]},"activity_evidence":{"$ref":"#/$defs/ActivityEvidence"},"execution":{"type":"object","additionalProperties":false,"required":["state","evidence_at","stale"],"properties":{"state":{"enum":["absent","starting","running","quiescent","unknown"]},"evidence_at":{"$ref":"#/$defs/Time"},"stale":{"type":"boolean"}}},"queue_count":{"$ref":"#/$defs/Nat"},"effective_limits":{"$ref":"#/$defs/Limits"},"continuity":{"$ref":"#/$defs/Continuity"},"actions":{"$ref":"#/$defs/Actions"},"saved_profile":{"type":"object","additionalProperties":false,"required":["id","revision"],"properties":{"id":{"type":"string","minLength":1,"maxLength":256},"revision":{"type":"integer","minimum":1}}},"effective_profile":{"$ref":"#/$defs/AgentProfile"},"profile_digest":{"type":"string","pattern":"^[0-9a-f]{64}$"},"budget_consumption":{"type":"object","additionalProperties":false,"properties":{"provider_steps":{"$ref":"#/$defs/Nat"},"tokens":{"$ref":"#/$defs/Nat"},"tool_calls":{"$ref":"#/$defs/Nat"},"wall_time_ms":{"$ref":"#/$defs/Nat"}},"required":["provider_steps","tokens","tool_calls","wall_time_ms"]}}},
  "OpenReceipt":{"type":"object","additionalProperties":false,"required":["session","operation","snapshot"],"properties":{"session":{"$ref":"#/$defs/SessionRef"},"operation":{"$ref":"#/$defs/OpRef"},"snapshot":{"$ref":"#/$defs/SessionSnapshot"}}},
  "OperationState":{"type":"object","additionalProperties":false,"required":["operation","operation_key","revision","receipt","observation"],"properties":{"operation":{"$ref":"#/$defs/OpRef"},"operation_key":{"$ref":"#/$defs/Key"},"revision":{"$ref":"#/$defs/Pos"},"receipt":{"$ref":"#/$defs/OperationReceipt"},"observation":{"allOf":[{"$ref":"#/$defs/Await"},{"properties":{"subject_kind":{"const":"operation"}}}]}}},
  "GetValue":{"oneOf":[{"type":"object","additionalProperties":false,"required":["kind","value"],"properties":{"kind":{"const":"session"},"value":{"$ref":"#/$defs/SessionSnapshot"}}},{"type":"object","additionalProperties":false,"required":["kind","value"],"properties":{"kind":{"const":"work"},"value":{"$ref":"#/$defs/WorkState"}}},{"type":"object","additionalProperties":false,"required":["kind","value"],"properties":{"kind":{"const":"operation"},"value":{"$ref":"#/$defs/OperationState"}}}]},
  "Filter":{"type":"object","additionalProperties":false,"properties":{"workspace":{"type":"string","minLength":1,"maxLength":32},"definition":{"type":"string","minLength":1,"maxLength":256},"activity":{"enum":["idle","working","blocked","stalled"]},"lifecycle":{"enum":["opening","active","suspended","closing","closed"]}}},
  "ListPage":{"type":"object","additionalProperties":false,"required":["items"],"properties":{"items":{"type":"array","maxItems":64,"items":{"$ref":"#/$defs/SessionSnapshot"}},"next":{"$ref":"#/$defs/Cursor"}}},
  "Candidate":{"type":"object","additionalProperties":false,"required":["ref","kind","title","status","checked_at","reasons","features","actions"],"properties":{"ref":{"$ref":"#/$defs/Ref"},"kind":{"enum":["definition","profile"]},"revision":{"$ref":"#/$defs/Pos"},"title":{"type":"string","maxLength":512},"status":{"enum":["ready","missing","unconfigured","incompatible","unknown"]},"checked_at":{"$ref":"#/$defs/Time"},"reasons":{"type":"array","maxItems":64,"items":{"$ref":"#/$defs/Text"}},"features":{"$ref":"#/$defs/Refs"},"actions":{"$ref":"#/$defs/Actions"}}},
  "CatalogPage":{"type":"object","additionalProperties":false,"required":["items","complete","unavailable_count","diagnostics"],"properties":{"items":{"type":"array","maxItems":64,"items":{"$ref":"#/$defs/Candidate"}},"next":{"$ref":"#/$defs/Cursor"},"complete":{"type":"boolean"},"unavailable_count":{"$ref":"#/$defs/Nat"},"diagnostics":{"type":"array","maxItems":64,"items":{"$ref":"#/$defs/Fault"}}}},
  "McpScope":{"type":"object","additionalProperties":false,"properties":{"workspace_id":{"$ref":"#/$defs/Ref"},"name":{"$ref":"#/$defs/Ref"},"subpath":{"$ref":"#/$defs/Ref"},"path_prefix":{"$ref":"#/$defs/Ref"},"scope":{"$ref":"#/$defs/Ref"},"access":{"enum":["read","write"]},"methods":{"$ref":"#/$defs/Refs"},"definitions":{"$ref":"#/$defs/Refs"},"operations":{"$ref":"#/$defs/Refs"},"traits":{"$ref":"#/$defs/Refs"},"audiences":{"$ref":"#/$defs/Refs"}}},
  "ProfileBee":{"type":"object","additionalProperties":false,"properties":{"permission_answers":{"enum":["provider","ask","deny"]},"mcp":{"type":"array","maxItems":64,"items":{"type":"object","additionalProperties":false,"properties":{"tool":{"$ref":"#/$defs/Ref"},"scope":{"$ref":"#/$defs/McpScope"}},"required":["tool","scope"]}},"files":{"type":"array","maxItems":64,"items":{"type":"object","additionalProperties":false,"properties":{"workspace_id":{"$ref":"#/$defs/Ref"},"resource":{"$ref":"#/$defs/Ref"},"subpath":{"type":"string","maxLength":4096},"access":{"enum":["read","write"]}},"required":["workspace_id","resource","subpath","access"]}},"workspaces":{"type":"array","maxItems":64,"items":{"type":"object","additionalProperties":false,"properties":{"workspace_id":{"$ref":"#/$defs/Ref"},"operations":{"$ref":"#/$defs/Refs"}},"required":["workspace_id","operations"]}},"credential_refs":{"$ref":"#/$defs/Refs"},"approval_leases":{"$ref":"#/$defs/Refs"}}},
  "ProfileProvider":{"type":"object","additionalProperties":false,"properties":{"model":{"$ref":"#/$defs/Ref"},"effort":{"$ref":"#/$defs/Ref"},"permission_mode":{"$ref":"#/$defs/Ref"},"tool_allow":{"$ref":"#/$defs/Refs"},"tool_deny":{"$ref":"#/$defs/Refs"},"system_prompt_append":{"type":"string","maxLength":4096},"options":{"type":"object","maxProperties":64},"env":{"type":"object","maxProperties":64,"additionalProperties":{"oneOf":[{"type":"object","additionalProperties":false,"properties":{"kind":{"const":"literal"},"value":{"type":"string","maxLength":4096}},"required":["kind","value"]},{"type":"object","additionalProperties":false,"properties":{"kind":{"const":"credential"},"credential_ref":{"$ref":"#/$defs/Ref"}},"required":["kind","credential_ref"]}]}}}},
  "AgentProfile":{"type":"object","additionalProperties":false,"properties":{"schema_revision":{"const":"bee.agent-profile@3"},"name":{"type":"string","minLength":1,"maxLength":80},"definition_ref":{"$ref":"#/$defs/Ref"},"driver_binding_ref":{"$ref":"#/$defs/Ref"},"provider":{"$ref":"#/$defs/ProfileProvider"},"bee":{"$ref":"#/$defs/ProfileBee"},"placement":{"$ref":"#/$defs/Placement"},"workdir":{"$ref":"#/$defs/Workdir"},"thread":{"type":"object","additionalProperties":false,"properties":{"thread_id":{"$ref":"#/$defs/Ref"}},"required":["thread_id"]},"agent_ref":{"$ref":"#/$defs/Ref"},"owner_component_revision":{"$ref":"#/$defs/Pos"},"spec_digest":{"type":"string","pattern":"^[0-9a-f]{64}$"}},"required":["schema_revision","name","definition_ref","driver_binding_ref","provider","bee"]},
  "Placement":{"oneOf":[{"type":"object","additionalProperties":false,"properties":{"kind":{"const":"native"},"home":{"enum":["private","machine"]}},"required":["kind","home"]},{"type":"object","additionalProperties":false,"properties":{"kind":{"const":"docker"},"profile_ref":{"$ref":"#/$defs/Ref"},"overrides":{"type":"object"}},"required":["kind","profile_ref"]}]}
 },
 "tools":[
  {"name":"session_catalog","description":"Choose a ready admitted definition or profile using locate. Starts nothing and grants nothing. Set include_unavailable to show readiness reasons. Optional node selects a peer bee; omit it for local behavior. The receiving bee requires the person's allowance.","inputSchema":{"type":"object","additionalProperties":false,"properties":{"definition_ref":{"$ref":"#/$defs/Ref"},"query":{"type":"string","maxLength":80},"sort":{"enum":["name","driver"]},"kind":{"enum":["definition","profile"],"default":"definition"},"include_unavailable":{"type":"boolean","default":false},"cursor":{"$ref":"#/$defs/Cursor"},"node":{"type":"string","minLength":1,"maxLength":160,"pattern":"^[A-Za-z0-9_.-]+$"}}},"outputSchema":{"allOf":[{"$ref":"#/$defs/Reply"},{"properties":{"value":{"$ref":"#/$defs/CatalogPage"}}}]}},
  {"name":"session_open","description":"Open an agent session: the agent's own program starts in a terminal that Bee keeps running whether or not anyone watches; the person can open it from Sessions. Keep its exact ref; send it messages with session_send and close it with session_close. Reuse this key after a lost reply; changing input under the key is a conflict. Optional node selects a peer bee; omit it for local behavior. The receiving bee requires the person's allowance.","inputSchema":{"type":"object","additionalProperties":false,"required":["spec","operation_key"],"properties":{"spec":{"$ref":"#/$defs/ManagedSpec"},"operation_key":{"$ref":"#/$defs/Key"},"node":{"type":"string","minLength":1,"maxLength":160,"pattern":"^[A-Za-z0-9_.-]+$"}}},"outputSchema":{"allOf":[{"$ref":"#/$defs/MutationReply"},{"properties":{"value":{"$ref":"#/$defs/OpenReceipt"}}}]}},
  {"name":"session_run","description":"Open an agent session and send its first message. Returns a WorkRef receipt, not the answer; await that work for the agent's reply. Reuse this key after a lost reply; changing input under the key is a conflict. Optional node selects a peer bee; omit it for local behavior. The receiving bee requires the person's allowance.","inputSchema":{"type":"object","additionalProperties":false,"required":["spec","input","operation_key"],"properties":{"spec":{"$ref":"#/$defs/ManagedSpec"},"input":{"$ref":"#/$defs/Input"},"output":{"$ref":"#/$defs/Ref"},"operation_key":{"$ref":"#/$defs/Key"},"node":{"type":"string","minLength":1,"maxLength":160,"pattern":"^[A-Za-z0-9_.-]+$"}}},"outputSchema":{"allOf":[{"$ref":"#/$defs/MutationReply"},{"properties":{"value":{"$ref":"#/$defs/WorkReceipt"}}}]}},
  {"name":"session_send","description":"Send the session a message: a task, follow-up or correction. It is typed into the agent's terminal when the agent finishes its current turn; a stopped session resumes to take it. Await the WorkRef receipt for the agent's reply. Reuse this key after a lost reply; changing input under the key is a conflict. Optional node selects a peer bee; omit it for local behavior. The receiving bee requires the person's allowance.","inputSchema":{"type":"object","additionalProperties":false,"required":["session","input","operation_key"],"properties":{"session":{"$ref":"#/$defs/SessionRef"},"input":{"$ref":"#/$defs/Input"},"output":{"$ref":"#/$defs/Ref"},"operation_key":{"$ref":"#/$defs/Key"},"node":{"type":"string","minLength":1,"maxLength":160,"pattern":"^[A-Za-z0-9_.-]+$"}}},"outputSchema":{"allOf":[{"$ref":"#/$defs/MutationReply"},{"properties":{"value":{"$ref":"#/$defs/WorkReceipt"}}}]}},
  {"name":"session_await","description":"Wait up to timeout_ms (default 30000, at most 60000) for one exact work or operation to settle, then return its tagged ready, pending, blocked or uncertain observation. Pending means it is still running: call again. Queued/accepted is not done; timeout never cancels. Keep timeout_ms below your tool-call timeout. Optional node selects a peer bee; omit it for local behavior. The receiving bee requires the person's allowance.","inputSchema":{"type":"object","additionalProperties":false,"required":["subject"],"properties":{"subject":{"$ref":"#/$defs/Subject"},"timeout_ms":{"$ref":"#/$defs/Timeout"},"node":{"type":"string","minLength":1,"maxLength":160,"pattern":"^[A-Za-z0-9_.-]+$"}}},"outputSchema":{"allOf":[{"$ref":"#/$defs/Reply"},{"properties":{"value":{"$ref":"#/$defs/Await"}}}]}},
  {"name":"session_join","description":"Join an exact ordered work set, waiting up to timeout_ms (default 30000, at most 60000) until the policy decides; returns every child's observation. Defaults to all_success; uncertain work remains unresolved. Pending means call again. Reuse this key after a lost reply; changing input under the key is a conflict. Optional node selects a peer bee; omit it for local behavior. The receiving bee requires the person's allowance.","inputSchema":{"type":"object","additionalProperties":false,"required":["works","operation_key"],"properties":{"works":{"$ref":"#/$defs/Works"},"policy":{"enum":["all_success","all_settled","first_success","quorum"],"default":"all_success"},"quorum":{"type":"integer","minimum":1,"maximum":64},"timeout_ms":{"$ref":"#/$defs/Timeout"},"operation_key":{"$ref":"#/$defs/Key"},"node":{"type":"string","minLength":1,"maxLength":160,"pattern":"^[A-Za-z0-9_.-]+$"}},"if":{"required":["policy"],"properties":{"policy":{"const":"quorum"}}},"then":{"required":["quorum"]},"else":{"not":{"required":["quorum"]}}},"outputSchema":{"allOf":[{"$ref":"#/$defs/MutationReply"},{"properties":{"value":{"$ref":"#/$defs/JoinAwait"}}}]}},
  {"name":"session_get","description":"Inspect an exact session, work or operation; or recover an operation by your saved operation_key in your caller/workspace namespace. Never infer work completion from an attempt or newest run. Optional node selects a peer bee; omit it for local behavior. The receiving bee requires the person's allowance.","inputSchema":{"type":"object","additionalProperties":false,"properties":{"session":{"$ref":"#/$defs/SessionRef"},"work":{"$ref":"#/$defs/WorkRef"},"operation":{"$ref":"#/$defs/OpRef"},"node":{"type":"string","minLength":1,"maxLength":160,"pattern":"^[A-Za-z0-9_.-]+$"}},"oneOf":[{"required":["session"]},{"required":["work"]},{"required":["operation"]}]},"outputSchema":{"allOf":[{"$ref":"#/$defs/Reply"},{"properties":{"value":{"$ref":"#/$defs/GetValue"}}}]}},
  {"name":"session_list","description":"List durable sessions, including idle and closed sessions. Filter by workspace, definition, lifecycle or activity; new-launch availability never filters existing sessions. Optional node selects a peer bee; omit it for local behavior. The receiving bee requires the person's allowance.","inputSchema":{"type":"object","additionalProperties":false,"properties":{"filter":{"$ref":"#/$defs/Filter"},"cursor":{"$ref":"#/$defs/Cursor"},"node":{"type":"string","minLength":1,"maxLength":160,"pattern":"^[A-Za-z0-9_.-]+$"}}},"outputSchema":{"allOf":[{"$ref":"#/$defs/Reply"},{"properties":{"value":{"$ref":"#/$defs/ListPage"}}}]}},
